export function getPracticePathBySlug(slugInput) {
  const slug = (slugInput || '').toString().trim().toLowerCase();
  return practicePaths.find((row) => (row.slug || '').toString().toLowerCase() === slug) || null;
}

export function getPracticePathByLegacyAlias(slugInput) {
  const slug = (slugInput || '').toString().trim().toLowerCase();
  return practicePaths.find((row) => Array.isArray(row.legacyAliases) && row.legacyAliases.some((alias) => (alias || '').toString().toLowerCase() === slug)) || null;
}
